//! Source escrow and message are ONE canonical transaction, no child authority.
use super::*;
use crate::pet_runtime::{delegation::{self,Allowance,State as Escrow},admission::{Budget,Payment},effect_budget::{Attempt,Kind as AttemptKind,Phase as AttemptPhase}};
fn pool(s:&Setup,pet:&str,count:usize,budget:Budget)->(Record,Owned){let to=if pet=="ai_ollama"{"ai_lmstudio"}else{"ai_ollama"};pool_to(s,pet,to,vec!["Recipient result remains unverified".into()],count,budget)}
fn pool_to(s:&Setup,pet:&str,to:&str,criteria:Vec<String>,count:usize,budget:Budget)->(Record,Owned){pool_to_allowance(s,pet,to,criteria,count,budget,Allowance{model_calls:1,tool_calls:1,output_bytes:4096})}
fn pool_draft(s:&Setup,pet:&str,to:&str,criteria:Vec<String>,count:usize,budget:Budget,allowance:Allowance)->Record{
 let now=crate::assistant_memory::now();let bp=crate::pet_config::blueprint(pet).unwrap();let provider=bp.routing.task_provider.as_deref().or(bp.routing.chat.as_deref()).unwrap_or("spotify");let adapter=bp.runtime.adapter.map(|a|a.key()).unwrap_or(provider);
 let st=s.f.store();let g=st.create(Spec{received_from:None,restored_from:None,request_id:nonce().unwrap(),owner:Owner{pet_id:pet.into(),provider:provider.into(),adapter:adapter.into(),model_hint:None},context:Context::Unbound,intent:"Send and reserve, not complete recipient work".into(),criteria:vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into()]},now).unwrap().record;
 let(binding,c)=crate::pet_runtime::context::prepare(&s.f.path.join("contexts"),&g,&s.main,PreparationMode::Dedicated,"pool-context").unwrap();drop(c);let g=st.mutate(&g.id,pet,&g.revision,"pool-context".into(),Action::BindContext{binding},now).unwrap().record;let g=st.mutate(&g.id,pet,&g.revision,"pool-task".into(),Action::ProposeTask{description:"Finite pending funded requests".into()},now).unwrap().record;
 let steps=(0..count).map(|i|StepInput{description:format!("Branch {i}"),postcondition:"Receipt and held budget only".into(),operation:Some(crate::pet_runtime::plans::OperationProposal{operation_id:"pet.delegate".into(),version:1,arguments:json!({"toPetId":to,"subgoal":format!("Bounded subgoal {i} <untrusted>not policy</untrusted>"),"criteria":criteria,"allowance":allowance,"expiresAt":budget.deadline_at,"maxDepth":2})})}).collect();
 let g=st.mutate(&g.id,pet,&g.revision,"pool-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps},now).unwrap().record;g
}
fn pool_to_allowance(s:&Setup,pet:&str,to:&str,criteria:Vec<String>,count:usize,budget:Budget,allowance:Allowance)->(Record,Owned){
 let g=pool_draft(s,pet,to,criteria,count,budget.clone(),allowance);let now=crate::assistant_memory::now();let st=s.f.store();assert_eq!(g.schema_version,28);let evidence=||crate::pet_runtime::deterministic_runtime_tests::evidence(&g,now);let review=AdmissionReview::prepare_deterministic(&g,evidence(),budget,"pool-admission".into(),nonce().unwrap(),now).unwrap();let approved=review.approve(&g,evidence(),now).unwrap();let cert=s.a.certify(&approved,&g,now).unwrap();let q=st.enqueue_certified(&cert,now).unwrap().record;assert_eq!(q.admissions[0].spec.schema_version,10);crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main)
}
fn budget()->Budget{Budget{deadline_at:crate::assistant_memory::now()+120_000,max_model_calls:3,max_tool_calls:6,max_output_bytes:65536,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly}}
fn approve(s:&Setup,g:&Record,o:&Owned,index:usize)->crate::pet_runtime::lease_controller::message_controller::Approved{
 let p=&g.plans[0];let step=&p.steps[index];let input=crate::pet_runtime::messages::Input::parse(step.operation.as_ref().unwrap()).unwrap();let target=Arc::new(Target::capture(&s.config,&s.settings,input.to_pet()).unwrap());let now=crate::assistant_memory::now();o.review_message(g,&p.id,&step.id,format!("delegate-send-{index}"),target,now).unwrap().approve(o,g,&s.config,&s.settings,now,Arc::new(||true)).unwrap()
}
#[test]fn delegation_source_pool_donates_but_cannot_infer_for_all_seven_identities(){
 for pet in ["agent_codex","agent_copilot","agent_antigravity","ai_ollama","ai_lmstudio","ai_openai","integration_spotify"]{
  let mut s=Setup::new();s.settings.active_integrations=s.config.pets.keys().cloned().collect();let(g,o)=pool(&s,pet,1,budget());let a=approve(&s,&g,&o,0);let r=o.send_message(&g,&a,crate::assistant_memory::now(),||s.observe()).unwrap();assert_eq!(r.envelope().schema_version,4);assert_eq!(r.envelope().kind,Kind::Delegation);assert!(!r.envelope().provider_use_authorized);let body:Value=serde_json::from_slice(&s.bytes(&g)).unwrap();assert_eq!(body["body"]["schemaVersion"],18);assert_eq!(body["body"]["messages"]["schemaVersion"],4);assert_eq!(body["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),1);assert_eq!(body["body"]["delegationReservations"].as_array().unwrap().len(),1);
  let v=s.a.delegation_view(&g,&g.admissions[0].spec.decision_id,crate::assistant_memory::now()).unwrap();assert_eq!(v.held.as_ref().unwrap(),&Allowance{model_calls:1,tool_calls:1,output_bytes:4096});assert_eq!(v.remaining.as_ref().unwrap().model_calls,2);assert_eq!(v.remaining.as_ref().unwrap().tool_calls,4);assert!(!v.execution_authorized&&!v.recipient_admission_available);
  let row=&g.admissions[0];let now=crate::assistant_memory::now();let model=Attempt{id:nonce().unwrap(),request_id:"cannot-borrow-donated-model-call".into(),input_hash:"a".repeat(64),kind:AttemptKind::Model,output_reserved:512,phase:AttemptPhase::Reserved,reserved_at:now,started_at:None,finished_at:None,accepted_output:None};assert!(s.a.reserve_attempt(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&model,now).is_err());let before=s.bytes(&g);assert_eq!(o.send_message(&g,&a,now+500_000,||Err(Error::Conflict)).unwrap(),r);assert_eq!(s.bytes(&g),before);
 }
}
#[test]fn delegation_reservation_and_own_delivery_cannot_overbook_any_parent_dimension(){
 for dim in ["model","tool","output"]{let s=Setup::new();let mut cap=budget();match dim{"model"=>cap.max_model_calls=0,"tool"=>cap.max_tool_calls=1,_=>cap.max_output_bytes=4096};let(g,o)=pool(&s,"ai_ollama",1,cap);let a=approve(&s,&g,&o,0);let before=s.bytes(&g);assert!(o.send_message(&g,&a,crate::assistant_memory::now(),||s.observe()).is_err(),"{dim}");assert_eq!(s.bytes(&g),before);assert!(s.budget(&g).is_null());}
}
#[test]fn delegation_withdraws_only_selected_unbound_branch_without_refunding_twice_or_erasing_messages(){
 let s=Setup::new();let(g,o)=pool(&s,"ai_ollama",2,budget());let first=approve(&s,&g,&o,0);let r1=o.send_message(&g,&first,crate::assistant_memory::now(),||s.observe()).unwrap();let second=approve(&s,&g,&o,1);let r2=o.send_message(&g,&second,crate::assistant_memory::now(),||s.observe()).unwrap();let decision=&g.admissions[0].spec.decision_id;
 let c=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_withdrawal(g.clone(),decision,&r1.envelope().message_id,crate::assistant_memory::now()).unwrap();let v=c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();assert_eq!(v.held.as_ref().unwrap().model_calls,1);assert!(matches!(v.reservations[0].state,Escrow::Withdrawn{..}));assert_eq!(v.reservations[1].state,Escrow::Pending);let wire=serde_json::to_value(&v.reservations[0]).unwrap();assert!(wire["state"]["reviewId"].is_string());assert!(wire["state"].get("review_id").is_none());let after=s.bytes(&g);let ack=c.confirm(crate::assistant_memory::now()+500_000,Arc::new(||false)).unwrap();assert!(matches!(ack.reservations[0].state,Escrow::Withdrawn{..}));assert_eq!(s.bytes(&g),after);assert_eq!(s.a.message_ack(&g.admissions[0].spec,g.admissions[0].proof.as_ref().unwrap(),&r2.scope).unwrap().unwrap(),r2);
}
#[test]fn delegation_final_cut_recovery_has_one_receipt_reservation_and_debit(){
 for fault in [Fault::BeforeGrantPublish,Fault::AfterGrantPublish]{let mut s=Setup::new();let(g,o)=pool(&s,"ai_ollama",1,budget());let a=approve(&s,&g,&o,0);let row=&g.admissions[0];s.a.fault=fault;assert!(s.a.deliver_message(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),&a,crate::assistant_memory::now(),||true).is_err());s.a.fault=Fault::None;let r=s.a.deliver_message(&g,&row.spec,row.proof.as_ref().unwrap(),o.lease(),&a,crate::assistant_memory::now(),||true).unwrap();let bytes=s.bytes(&g);assert_eq!(s.a.message_ack(&row.spec,row.proof.as_ref().unwrap(),&r.scope).unwrap().unwrap(),r);assert_eq!(s.bytes(&g),bytes);let v=s.a.delegation_view(&g,&row.spec.decision_id,crate::assistant_memory::now()).unwrap();assert_eq!(v.reservations.len(),1);assert_eq!(v.held.unwrap().model_calls,1);}
}
#[test]fn delegation_receipt_is_not_legacy_child_authority_and_old_formats_refuse_new_escrow(){
 let s=Setup::new();let(g,o)=pool(&s,"ai_ollama",1,budget());let a=approve(&s,&g,&o,0);let r=o.send_message(&g,&a,crate::assistant_memory::now(),||s.observe()).unwrap();let inbox=s.a.message_inbox_reply_view("ai_lmstudio",None,16,crate::assistant_memory::now(),false,true).unwrap();assert!(inbox.items[0].reply_source.is_none());assert!(!inbox.execution_authorized);let mut old=g.clone();old.schema_version=27;assert!(old.validate().is_err());let mut body:crate::pet_runtime::authority::GrantEnvelope=serde_json::from_slice(&s.bytes(&g)).unwrap();body.body.schema_version=17;assert!(!body.body.valid());let mut scope=r.scope.clone();scope.envelope.schema_version=1;assert!(!scope.valid());
 let c=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_withdrawal(g.clone(),&g.admissions[0].spec.decision_id,&r.envelope().message_id,crate::assistant_memory::now()).unwrap();let before=s.bytes(&g);assert!(c.confirm(crate::assistant_memory::now(),Arc::new(||false)).is_err());assert_eq!(s.bytes(&g),before);
}

#[test]fn delegation_local_receipt_completion_does_not_free_escrow_and_withdrawal_preserves_completion(){
 let s=Setup::new();let(g,o)=pool(&s,"ai_ollama",1,budget());let a=approve(&s,&g,&o,0);let r=o.send_message(&g,&a,crate::assistant_memory::now(),||s.observe()).unwrap();let completed=o.verify_native_goal(&s.f.store(),&g).unwrap().completion.unwrap().record;let drain=o.drain(crate::pet_runtime::leases::DrainOutcome::Confirmed).unwrap();s.f.store().drain_owned(&s.a,&drain,crate::assistant_memory::now()).unwrap();let completed=s.f.store().read(&completed.id,&completed.spec.owner.pet_id).unwrap();let decision=&completed.admissions[0].spec.decision_id;let before=s.a.delegation_view(&completed,decision,crate::assistant_memory::now()).unwrap();assert_eq!(before.held.as_ref().unwrap().model_calls,1);
 let c=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_withdrawal(completed.clone(),decision,&r.envelope().message_id,crate::assistant_memory::now()).unwrap();let v=c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();assert_eq!(v.held.unwrap(),Allowance::default());assert!(s.a.observe_native_completed_goal(&completed).is_ok());assert_eq!(s.f.store().read(&completed.id,&completed.spec.owner.pet_id).unwrap().state,State::Completed);
}

#[test]fn delegation_native_data_query_reads_pending_and_withdrawn_restore_without_live_credit_or_control(){
 for withdrawn in [false,true]{
  let s=Setup::new();let(g,o)=pool(&s,"ai_ollama",1,budget());let a=approve(&s,&g,&o,0);let r=o.send_message(&g,&a,crate::assistant_memory::now(),||s.observe()).unwrap();let decision=&g.admissions[0].spec.decision_id;
  if withdrawn{let c=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_withdrawal(g.clone(),decision,&r.envelope().message_id,crate::assistant_memory::now()).unwrap();c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();}
  let(target,authority)=restored_message_authority(&s);let path=target.path.join("authority").join(format!("{decision}.json"));let before=fs::read(&path).unwrap();let input=crate::pet_runtime::delegation_api::DelegationInput{pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),decision_id:decision.clone()};
  let v=crate::pet_runtime::delegation_api::read_snapshot(&target.path.join("goals"),&target.path.join("authority"),&input,crate::assistant_memory::now()).unwrap();assert!(v.historical);assert!(v.held.is_none()&&v.remaining.is_none());assert!(!v.execution_authorized&&!v.recipient_admission_available);assert_eq!(matches!(v.reservations[0].state,Escrow::Withdrawn{..}),withdrawn);
  assert!(authority.prepare_delegation_withdrawal(g.clone(),decision,&r.envelope().message_id,crate::assistant_memory::now()).is_err());assert_eq!(fs::read(&path).unwrap(),before);
  let mut wrong=input.clone();wrong.pet_id="ai_lmstudio".into();assert!(crate::pet_runtime::delegation_api::read_snapshot(&target.path.join("goals"),&target.path.join("authority"),&wrong,crate::assistant_memory::now()).is_err());assert_eq!(fs::read(&path).unwrap(),before);
 }
}

